// Builds @ems/tokens from the W3C DTCG sources in ../tokens with Style Dictionary.
//
// Outputs (committed, regenerated by `npm run tokens:build`; CI fails if they drift):
//   src/generated/tokens.css   primitives + foundation scales on :root; light semantic + component
//                              on :root, dark on [data-theme="dark"] and under prefers-color-scheme
//   src/generated/tokens.json  every token with resolved light/dark values (gallery, contrast gate)
//   src/generated/tokens.ts    the same data as a typed, tree-shakeable TS export
//
// Four tiers: primitive (raw ramps and literals, build-only), foundation (theme-independent scales
// components may use: space, radius, border-width, duration, easing, z, font.family), semantic
// (roles, per theme) and component. Two Style Dictionary instances are built, one per theme; only
// the semantic theme file differs. Semantic and component tokens are emitted as references
// (var(--ems-…)), so component tokens follow the active theme without a dark copy, and only the
// primitive colours carry literal values (OKLCH, with an sRGB hex fallback block).
import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import StyleDictionary from 'style-dictionary';
import { transforms } from 'style-dictionary/enums';
import { formattedVariables } from 'style-dictionary/utils';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const outDir = join(root, 'src', 'generated');
const PREFIX = 'ems';
// Style Dictionary globs need forward slashes, also on Windows.
const posix = (...parts) => join(...parts).replaceAll('\\', '/');
const LAYER_ORDER = '@layer reset, tokens, base, components, utilities;';

/** @typedef {'primitive' | 'foundation' | 'semantic' | 'component'} Tier */

/** @param {{ filePath: string }} token @returns {Tier} */
function tierOf(token) {
  const path = token.filePath.replaceAll('\\', '/');
  if (path.includes('/semantic/')) return 'semantic';
  if (path.includes('/component/')) return 'component';
  if (path.includes('/foundation/')) return 'foundation';
  return 'primitive';
}

// Emits only the declarations (no selector) so the script can place them in theme blocks.
// The dictionary keeps the full token tree, so references to tokens that are not emitted in this
// block (e.g. dark semantic -> primitive) still become var(--ems-…) instead of resolved values.
StyleDictionary.registerFormat({
  name: 'ems/css-declarations',
  format: async ({ dictionary, options }) => {
    /** @type {Tier[]} */
    const tiers = options.tiers;
    const allTokens = dictionary.allTokens.filter((t) => tiers.includes(tierOf(t)));
    return formattedVariables({
      format: 'css',
      dictionary: { ...dictionary, allTokens },
      outputReferences: options.outputReferences === true,
      usesDtcg: true,
      formatting: { indentation: '  ', commentStyle: 'none' },
    });
  },
});

const cssTransforms = [
  transforms.attributeCti,
  transforms.nameKebab,
  transforms.sizeRem,
  transforms.timeSeconds,
  transforms.fontFamilyCss,
  transforms.cubicBezierCss,
];
// After the colour transform, so the colours inside a shadow are already CSS strings.
const shadowTransforms = [transforms.shadowCssShorthand];

/** @param {'light' | 'dark'} theme */
function config(theme) {
  return {
    source: [
      posix(root, 'tokens/primitive/**/*.json'),
      posix(root, 'tokens/foundation/**/*.json'),
      posix(root, 'tokens/semantic/base.json'),
      posix(root, `tokens/semantic/${theme}.json`),
      posix(root, 'tokens/component/**/*.json'),
    ],
    usesDtcg: true,
    // Collisions, broken references and filtered references fail the build.
    log: { warnings: 'error', verbosity: 'default' },
    platforms: {
      css: {
        prefix: PREFIX,
        transforms: [...cssTransforms, transforms.colorOklch, ...shadowTransforms],
        files: [
          {
            destination: 'primitives.css',
            format: 'ems/css-declarations',
            options: { outputReferences: true, tiers: ['primitive'] },
          },
          {
            destination: 'foundation.css',
            format: 'ems/css-declarations',
            options: { outputReferences: true, tiers: ['foundation'] },
          },
          {
            // Component tokens are re-declared per theme scope: a custom property's var() is
            // resolved on the element that declares it, so a nested [data-theme] needs its own copy.
            destination: 'themed.css',
            format: 'ems/css-declarations',
            options: { outputReferences: true, tiers: ['semantic', 'component'] },
          },
        ],
      },
      hex: {
        prefix: PREFIX,
        transforms: [...cssTransforms, transforms.colorHex, ...shadowTransforms],
        files: [
          {
            destination: 'fallback.css',
            format: 'ems/css-declarations',
            filter: (token) => token.$type === 'color',
            options: { outputReferences: false, tiers: ['primitive'] },
          },
        ],
      },
    },
  };
}

/** @param {StyleDictionary} sd @param {string} platform @param {string} destination */
async function formatted(sd, platform, destination) {
  const files = await sd.formatPlatform(platform);
  const file = files.find((f) => f.destination === destination);
  if (!file) throw new Error(`No ${destination} output for platform ${platform}`);
  return String(file.output).trimEnd();
}

/** @param {unknown} original @returns {string | null} */
function referenceOf(original) {
  return typeof original === 'string' && /^\{[^}]+\}$/.test(original)
    ? original.slice(1, -1)
    : null;
}

/** @param {StyleDictionary} sd */
async function tokenData(sd) {
  const css = await sd.getPlatformTokens('css');
  const hex = await sd.getPlatformTokens('hex');
  const hexByName = new Map(hex.allTokens.map((t) => [t.name, t.$value]));
  return css.allTokens.map((t) => ({
    name: t.path.join('.'),
    cssVar: `--${t.name}`,
    type: t.$type,
    tier: tierOf(t),
    value: t.$value,
    ...(t.$type === 'color' ? { hex: hexByName.get(t.name) } : {}),
    ref: referenceOf(t.original.$value),
    ...(t.$description ? { description: t.$description } : {}),
  }));
}

const indent = (text, by) =>
  text
    .split('\n')
    .map((line) => (line.trim() ? by + line : line))
    .join('\n');

async function main() {
  const light = new StyleDictionary(config('light'));
  const dark = new StyleDictionary(config('dark'));
  await Promise.all([light.hasInitialized, dark.hasInitialized]);

  const primitiveVars = await formatted(light, 'css', 'primitives.css');
  const foundationVars = await formatted(light, 'css', 'foundation.css');
  const lightVars = await formatted(light, 'css', 'themed.css');
  const darkVars = await formatted(dark, 'css', 'themed.css');
  const hexFallback = await formatted(light, 'hex', 'fallback.css');

  const header = [
    '/**',
    ' * @ems/tokens: generated by projects/tokens/scripts/build-tokens.mjs. Do not edit.',
    ' * Direction D, Daylight (decision D30). Variable names: docs/design/token-contract.md.',
    ' */',
  ].join('\n');

  const css = `${header}
${LAYER_ORDER}

@layer tokens {
  /* Primitive tier: raw scales. Components never use these directly. */
  :root {
${indent(primitiveVars, '  ')}
  }

  /* Foundation tier: theme-independent scales components may use (space, radius, motion, z, fonts). */
  :root {
${indent(foundationVars, '  ')}
  }

  /* sRGB fallback for engines without OKLCH; every other tier references these. */
  @supports not (color: oklch(0% 0 0)) {
    :root {
${indent(hexFallback, '    ')}
    }
  }

  /* Semantic + component tiers, light theme (default, and nested [data-theme='light']). */
  :root,
  [data-theme='light'] {
${indent(lightVars, '  ')}
  }

  /* Dark theme, explicit choice. */
  [data-theme='dark'] {
${indent(darkVars, '  ')}
  }

  /* Dark theme, following the OS when no explicit light choice was made. */
  @media (prefers-color-scheme: dark) {
    :root:not([data-theme='light']) {
${indent(darkVars, '    ')}
    }
  }
}
`;

  const lightTokens = await tokenData(light);
  const darkTokens = await tokenData(dark);
  const darkByName = new Map(darkTokens.map((t) => [t.name, t]));
  const missing = lightTokens.filter((t) => !darkByName.has(t.name)).map((t) => t.name);
  const extra = darkTokens
    .filter((t) => !lightTokens.some((l) => l.name === t.name))
    .map((t) => t.name);
  if (missing.length || extra.length) {
    throw new Error(
      `light.json and dark.json must declare the same paths.\n  only in light: ${missing.join(', ') || '-'}\n  only in dark: ${extra.join(', ') || '-'}`,
    );
  }

  const tokens = {};
  for (const t of lightTokens) {
    const d = darkByName.get(t.name);
    const themed = t.tier === 'semantic' || t.tier === 'component';
    tokens[t.name] = {
      cssVar: t.cssVar,
      type: t.type,
      tier: t.tier,
      ...(t.description ? { description: t.description } : {}),
      ...(themed
        ? {
            light: { value: t.value, ...(t.hex ? { hex: t.hex } : {}), ref: t.ref },
            dark: { value: d.value, ...(d.hex ? { hex: d.hex } : {}), ref: d.ref },
          }
        : { value: t.value, ...(t.hex ? { hex: t.hex } : {}) }),
    };
  }
  const json = { $schema: 'ems-tokens/1', prefix: `--${PREFIX}-`, tokens };

  // Breakpoints get their own small export (custom properties do not work inside @media, and
  // importing the whole `tokens` map into a component would bundle every token).
  const breakpoints = Object.fromEntries(
    lightTokens
      .filter((t) => t.name.startsWith('breakpoint.'))
      .map((t) => {
        const px = Number.parseFloat(String(t.value));
        if (!String(t.value).endsWith('px') || Number.isNaN(px)) {
          throw new Error(`${t.name} must be a px dimension, got ${t.value}`);
        }
        return [t.name.slice('breakpoint.'.length), px];
      }),
  );
  const mediaQueries = Object.fromEntries(
    Object.entries(breakpoints).map(([name, px]) => [name, `(max-width: ${px - 0.02}px)`]),
  );

  const ts = `${header}

export type TokenTier = 'primitive' | 'foundation' | 'semantic' | 'component';
export type ThemeName = 'light' | 'dark';

export interface ThemedValue {
  readonly value: string | number;
  readonly hex?: string;
  /** Dotted path of the referenced token, or null for a literal value. */
  readonly ref: string | null;
}

export interface PrimitiveToken {
  readonly cssVar: string;
  readonly type: string;
  readonly tier: 'primitive' | 'foundation';
  readonly description?: string;
  readonly value: string | number;
  readonly hex?: string;
}

export interface ThemedToken {
  readonly cssVar: string;
  readonly type: string;
  readonly tier: 'semantic' | 'component';
  readonly description?: string;
  readonly light: ThemedValue;
  readonly dark: ThemedValue;
}

export type EmsToken = PrimitiveToken | ThemedToken;

export const tokens = ${JSON.stringify(tokens, null, 2)} as const satisfies Readonly<Record<string, EmsToken>>;

export type TokenName = keyof typeof tokens;

/** CSS custom property reference for a token, e.g. cssVar('color.bg.surface') -> 'var(--ems-color-bg-surface)'. */
export function cssVar(name: TokenName): string {
  return \`var(\${tokens[name].cssVar})\`;
}

/**
 * Layout breakpoints in px (foundation \`breakpoint.*\`). Custom properties cannot be used in
 * \`@media\`, so component CSS repeats the matching MEDIA_QUERIES literal with a comment naming the
 * token; TS code (matchMedia) uses these constants.
 */
export const BREAKPOINTS = ${JSON.stringify(breakpoints, null, 2)} as const;

export type BreakpointName = keyof typeof BREAKPOINTS;

/** Media queries that match below each breakpoint, e.g. MEDIA_QUERIES.compact for matchMedia(). */
export const MEDIA_QUERIES = ${JSON.stringify(mediaQueries, null, 2)} as const satisfies Readonly<Record<BreakpointName, string>>;
`;

  await mkdir(outDir, { recursive: true });
  await writeFile(join(outDir, 'tokens.css'), css);
  await writeFile(join(outDir, 'tokens.json'), `${JSON.stringify(json, null, 2)}\n`);
  await writeFile(join(outDir, 'tokens.ts'), ts);

  const counts = { primitive: 0, foundation: 0, semantic: 0, component: 0 };
  for (const t of lightTokens) counts[t.tier] += 1;
  console.log(
    `@ems/tokens: ${lightTokens.length} tokens (primitive ${counts.primitive}, foundation ${counts.foundation}, semantic ${counts.semantic} x 2 themes, component ${counts.component}) -> ${relative(process.cwd(), outDir)}`,
  );
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
